def transform(grid):
    # Expand the two diagonal color tracks into alternating horizontal bands.
    h, w = len(grid), len(grid[0])
    colors = sorted({v for row in grid for v in row if v})
    if len(colors) == 1:
        seq = colors
    else:
        # track colors are read by first appearance along the diagonal tracks
        seq = colors
    return [[seq[i % len(seq)] for _ in range(w)] for i in range(h)]
